mapper.select:
/* ChkLst01Mapper.selectChkptInspectItemList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.CHKLST_TYPE AS chkLstType , A.INSPECT_ITEM_CD AS inspectItemCd , A.INSPECT_ITEM_SUBJ AS inspectItemSubj , A.SORT_IDX AS sortIdx , A.STR_DATE AS strDate , A.USE_YN AS useYn
, A.LINK_SRC_CMPNY_CD AS linkSrcCmpnyCd FROM TB_CHKPT_INSPECT_ITEM A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd}
AND A.CHKLST_TYPE = #{codeCd}
ORDER BY CHKLST_TYPE, SORT_IDX

mapper.insert:
/* ChkLst01Mapper.updateChkptInspectItemList */
UPDATE TB_CHKPT_INSPECT_ITEM
SET
	USE_YN = 'N'
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = now()
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND CHKLST_TYPE = #{chkLstType}
  AND INSPECT_ITEM_CD = #{inspectItemCd}

mapper.select:
/* ChkLst02Mapper.countUserSiteAuth */
SELECT COUNT(1)
FROM TB_USER_SITE_AUTH
WHERE 1=1
  AND CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD = #{gvUserCd}
  AND SITE_CD = #{siteCd}
  AND USE_YN = 'Y'

/* ChkLst02Mapper.selectCopySourceItemList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.CHKLST_TYPE AS chkLstType , A.INSPECT_ITEM_CD AS inspectItemCd , A.INSPECT_ITEM_SUBJ AS inspectItemSubj , A.SORT_IDX AS sortIdx , A.STR_DATE AS strDate , A.USE_YN AS useYn
, A.LINK_SRC_CMPNY_CD AS linkSrcCmpnyCd FROM TB_CHKPT_INSPECT_ITEM A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{srcSiteCd} AND A.CHKLST_TYPE = #{chkLstType} AND A.INSPECT_ITEM_CD IN
#{itemCd}
ORDER BY A.SORT_IDX, A.INSPECT_ITEM_CD

/* ChkLst02Mapper.selectMaxSortIdx */
SELECT IFNULL(MAX(A.SORT_IDX), 0)
FROM TB_CHKPT_INSPECT_ITEM A
WHERE 1=1
  AND A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{dstSiteCd}
  AND A.CHKLST_TYPE = #{chkLstType}
